@extends('admin.layout')
@section('content')<form class="panel" id="reset" style="max-width:480px;margin:40px auto"><h1>Reset password</h1><input type="hidden" name="token" value="{{request('token')}}"><label>Email<input name="email" type="email" value="{{request('email')}}" required></label><label>New password<input name="password" type="password" minlength="12" required></label><label>Confirm password<input name="password_confirmation" type="password" minlength="12" required></label><button>Reset password</button><p id="result" role="status"></p></form><script>document.getElementById('reset').addEventListener('submit',async e=>{e.preventDefault();const output=document.getElementById('result');try{const response=await fetch('/api/v1/reset-password',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const data=await response.json();output.textContent=data.message||'Unable to reset password.';}catch{output.textContent='Connection failed. Try again.'}});</script>@endsection
